PARAMS = ['V','k12','k21','CL']
def predict(df, p):
    t = df['t'].values; d = df['dose'].values
    out = np.zeros(len(df))
    A = np.array([[-(p['k12']+p['CL']/p['V']), p['k21']],[p['k12'], -p['k21']]])
    w, Vec = np.linalg.eig(A)
    for i,(dose,tt) in enumerate(zip(d,t)):
        y = Vec @ np.diag(np.exp(w*tt)) @ np.linalg.solve(Vec, np.array([dose,0.0]))
        out[i] = y[0]/p['V']
    return np.real(out)

